/**
 * Where body parts are on `assets/avatar-preview.png` (179 × 610), as fractions of the
 * image's width (x) and height (y). Generated by running MediaPipe Pose + Face Landmarker
 * on the avatar image itself: `services/api/scripts/compute_avatar_anchors.py`
 * (re-run it if the image changes). The waist uses the notebook's estimate (65 % of the way
 * from the shoulder line to the hip line), because hair and the raised arm touch the torso
 * outline on this picture.
 *
 * "a" / "b" = image-left / image-right. The avatar's own left side is on the image's right.
 */
import type { AvatarMeasurements } from './avatarProfileStore';
import { formatRatio, formatShare } from './avatarSummary';

export type Point = { x: number; y: number };

export const AVATAR_ANCHORS = {
  shoulderA: { x: 0.353, y: 0.21 },
  shoulderB: { x: 0.843, y: 0.208 },
  shoulderMid: { x: 0.598, y: 0.209 },
  elbow: { x: 0.93, y: 0.341 },
  wrist: { x: 0.773, y: 0.405 },
  waist: { x: 0.526, y: 0.371 },
  hipA: { x: 0.335, y: 0.453 },
  hipB: { x: 0.641, y: 0.463 },
  hipMid: { x: 0.488, y: 0.458 },
  knee: { x: 0.732, y: 0.676 },
  ankle: { x: 0.658, y: 0.876 },
  leftEye: { x: 0.435, y: 0.111 },
  rightEye: { x: 0.567, y: 0.098 },
  nose: { x: 0.504, y: 0.123 },
  lips: { x: 0.547, y: 0.143 },
  faceCenter: { x: 0.533, y: 0.116 },
} as const satisfies Record<string, Point>;

const A = AVATAR_ANCHORS;

function midpoint(p: Point, q: Point): Point {
  return { x: (p.x + q.x) / 2, y: (p.y + q.y) / 2 };
}

export type Annotation = {
  id: string;
  title: string;
  value: string;
  /** Where the dot sits and the callout line starts. */
  anchor: Point;
  /** Optional measured segment drawn on the body (e.g. shoulder to shoulder). */
  segment?: readonly [Point, Point];
  side: 'left' | 'right';
};

export function buildAnnotations(m: AvatarMeasurements): Annotation[] {
  const body = m.body;
  const face = m.face;
  const ofHeight = (value: number | null) => (value === null ? formatShare(null) : `${formatShare(value)} of height`);
  const ofFace = (value: number | null) => (value === null ? formatShare(null) : `${formatShare(value)} of face`);

  return [
    { id: 'face', title: 'Face shape', value: `W÷H ${formatRatio(face.face_width_to_height)}`, anchor: A.faceCenter, side: 'left' },
    {
      id: 'eyes',
      title: 'Eye spacing',
      value: ofFace(face.eye_distance_to_face_width),
      anchor: A.leftEye,
      segment: [A.leftEye, A.rightEye],
      side: 'left',
    },
    {
      id: 'shoulders',
      title: 'Shoulder width',
      value: ofHeight(body.shoulder_to_height),
      anchor: A.shoulderA,
      segment: [A.shoulderA, A.shoulderB],
      side: 'left',
    },
    {
      id: 'torso',
      title: 'Torso length',
      value: ofHeight(body.torso_to_height),
      anchor: midpoint(A.shoulderMid, A.hipMid),
      segment: [A.shoulderMid, A.hipMid],
      side: 'left',
    },
    { id: 'waist', title: 'Waist ÷ hips', value: formatRatio(m.torso.waist_to_hip), anchor: A.waist, side: 'left' },
    {
      id: 'hips',
      title: 'Hip width',
      value: ofHeight(body.hip_to_height),
      anchor: A.hipA,
      segment: [A.hipA, A.hipB],
      side: 'left',
    },
    { id: 'nose', title: 'Nose width', value: ofFace(face.nose_width_to_face_width), anchor: A.nose, side: 'right' },
    { id: 'lips', title: 'Lip width', value: ofFace(face.lip_width_to_face_width), anchor: A.lips, side: 'right' },
    {
      id: 'upperArm',
      title: 'Upper arm',
      value: ofHeight(body.upper_arm_to_height),
      anchor: midpoint(A.shoulderB, A.elbow),
      segment: [A.shoulderB, A.elbow],
      side: 'right',
    },
    {
      id: 'lowerArm',
      title: 'Lower arm',
      value: ofHeight(body.lower_arm_to_height),
      anchor: midpoint(A.elbow, A.wrist),
      segment: [A.elbow, A.wrist],
      side: 'right',
    },
    {
      id: 'upperLeg',
      title: 'Upper leg',
      value: ofHeight(body.upper_leg_to_height),
      anchor: midpoint(A.hipB, A.knee),
      segment: [A.hipB, A.knee],
      side: 'right',
    },
    {
      id: 'lowerLeg',
      title: 'Lower leg',
      value: ofHeight(body.lower_leg_to_height),
      anchor: midpoint(A.knee, A.ankle),
      segment: [A.knee, A.ankle],
      side: 'right',
    },
  ];
}

/**
 * Vertical positions (px) for one column of labels: each label stays as close as possible to its
 * anchor's height while keeping at least `minGap` between label centres and staying inside
 * [minY, maxY]. Input order does not matter; output is in the input order.
 */
export function layoutLabelCenters(anchorYs: readonly number[], minGap: number, minY: number, maxY: number): number[] {
  const order = anchorYs.map((y, index) => ({ y, index })).sort((a, b) => a.y - b.y);
  const placed = order.map((item) => item.y);

  for (let i = 0; i < placed.length; i += 1) {
    const floor = i === 0 ? minY : placed[i - 1] + minGap;
    placed[i] = Math.max(placed[i], floor);
  }
  for (let i = placed.length - 1; i >= 0; i -= 1) {
    const ceiling = i === placed.length - 1 ? maxY : placed[i + 1] - minGap;
    placed[i] = Math.min(placed[i], ceiling);
  }

  const result = new Array<number>(anchorYs.length);
  order.forEach((item, sortedIndex) => {
    result[item.index] = placed[sortedIndex];
  });
  return result;
}
